GF4_LIFECYCLE = ('c1', 'c2f3', 'c2stop', 'c2svc', 'c2init', 'c2rec',
                 'c2scan', 'c2links', 'c2linkb', 'c2save', 'diag', 'c3', 'c2linit', 'c2log', 'scanlog')


def gf4_tree(tree):
    """Private source tree keeps relative includes and runtime mutations honest."""
    import shutil
    copied = ('hwdev', 'kdebug', 'drivers', 'include', 'kernel', 'tools/tests')
    tree.mkdir()
    for rel in copied:
        shutil.copytree(ROOT/rel, tree/rel, dirs_exist_ok=True,
                        ignore=shutil.ignore_patterns('__pycache__'))
    for entry in ROOT.iterdir():
        target = tree/entry.name
        if entry.name.startswith('.') or target.exists():
            continue
        target.symlink_to(entry, target_is_directory=entry.is_dir())
    for entry in (ROOT/'tools').iterdir():
        target = tree/'tools'/entry.name
        if not target.exists():
            target.symlink_to(entry, target_is_directory=entry.is_dir())


def gf4_sources(tree, case, fixture=None):
    if case not in GF4_LIFECYCLE:
        return [*GF4_COMPONENTS[case], 'tools/tests/gf_accel_unbound_stubs.c']
    if case == 'c2linit':
        return ['kdebug/gfinit_decode.c', 'kdebug/gfinit_pll.c',
                'hwdev/gf/runner.c', 'hwdev/gf/save.c', 'hwdev/gf/pll.c',
                *[str(p.relative_to(tree)) for p in sorted((tree/'hwdev/gf/op').glob('*.c'))]]
    if case in ('c2save', 'diag'):
        names = ('save', 'modes', 'output', 'cursor', 'gamma', 'heads', 'pll_program',
                 'tmds', 'tv', 'modeset', 'transaction', 'timing', 'format', 'fifo',
                 'dpms', 'flip', 'palette')
        return ['hwdev/gf/display/'+n+'.c' for n in names]+[
            'kdebug/gfinit_pll.c', 'hwdev/gf_load_state.c']+([] if case=='diag' else ['tools/tests/gf4_modeload_print_host.c'])
    display = sorted((tree/'hwdev/gf/display').glob('*.c'))
    sources = [str(p.relative_to(tree)) for p in display]
    sources += ['tools/tests/gf4_platform_host.c', 'kdebug/gfinit_pll.c', 'kdebug/gfinit_decode.c',
                'hwdev/gf_load_state.c']
    # F4 startup now acquires F5 ROM, and module init publishes its service.
    # Keep those contracts real; only kernel allocation/time is a host seam.
    sources += ['hwdev/gf/'+n+'.c' for n in
                ('feature5_service', 'feature5_rom', 'feature5_links',
                 'perf', 'clock', 'ramclock', 'therm', 'volt', 'tile', 'state')]
    sources += ['drivers/video/geforce/'+n+'.c' for n in
                ('edid', 'tv_data', 'gf_display_data')]
    sources += ['hwdev/gf/'+n+'.c' for n in
                ('service', 'vram_view', 'accel_surface', 'accel_copy',
                 'runner', 'save', 'pll')]
    sources += [str(p.relative_to(tree)) for p in sorted((tree/'hwdev/gf/op').glob('*.c'))]
    sources += ['hwdev/gf/'+n+'.c' for n in
                ('master', 'mc', 'instmem', 'instmem_map', 'engine_stop', 'irq',
                 'foundation', 'fifo', 'push', 'dmaobj', 'ramht', 'grctx', 'gr',
                 'fence', 'fault', 'command_platform', 'command', 'accel_objects',
                 'accel_rop', 'accel_fill', 'accel_mono', 'accel_ifc', 'accel_m2mf',
                 'accel_transfer', 'accel_scale')]
    sources += ['tools/tests/gf_accel_unbound_stubs.c',
                'drivers/video/geforce/gf_hook.c',
                'drivers/video/geforce/gf_present_m2mf.c']
    if case != 'c3':
        sources += ['drivers/video/geforce/backend_geforce.c']
    if case in ('c1', 'scanlog'):
        sources += ['drivers/video/geforce/gf_present.c']
    if case == 'c3':
        sources += ['kernel/module/module_runtime.c', 'kernel/module/module_image.c',
                    'fs/vfs.c', 'drivers/base/dev.c']
    sources.append('tools/tests/recover_gf_dev_stub.c')
    # Follow the fixture include graph, including configurable SOURCE macros.
    import re
    included = set()
    def visit(path):
        if not path.is_file() or path in included:
            return
        included.add(path)
        for rel in re.findall(r'"([^"\n]+\.[ch])"', path.read_text()):
            dependency = (path.parent/rel).resolve()
            if dependency.is_relative_to(tree.resolve()):
                visit(dependency)
    visit(fixture or tree/f'tools/tests/gf4_{case}_host.c')
    return [rel for rel in dict.fromkeys(sources) if (tree/rel).resolve() not in included]


def gf4_case(tree, case, directory):
    from kernel_includes import include_flags
    import struct
    exe = directory/case
    flags = ['gcc', '-m32', '-march=i386', '-std=gnu11', '-O2', '-Wall', '-Wextra',
             '-Werror', '-Werror=vla', '-Wno-unused-parameter', '-ffreestanding',
             '-fno-pie', '-fno-stack-protector', '-ffunction-sections', '-fdata-sections',
             '-nostdlib', '-static', '-no-pie', '-Wl,--gc-sections',
             '-D__KERNEL_BUILD__', *include_flags(tree), '-I'+str(tree),
             '-I'+str(ROOT/'build/out/geforce')]
    if case in GF4_LIFECYCLE or case in ('b5', 'c0', 'c0log'):
        flags += ['-DGF_PRODUCTION_MODULE', '-DGF4_REAL_DISPLAY']
    if case == 'c2svc':
        flags += ['-DGF4_GUARD_LIFETIME']
    if case in ('c2scan', 'c2links', 'c2linkb'):
        flags += ['-DOS32_GEFORCE_MODULE']
    if case == 'c2links' or case in GF4_LIFECYCLE:
        flags[1:1] = ['-I'+str(tree/'tools/tests/host_arch')]
    sources = gf4_sources(tree, case)
    objects = []
    if case == 'c3':
        # Preserve C3's ABI table probes while linking C1's real metadata hook.
        obj = directory/'c3_backend.o'
        aliases = ['geforce_backend_ops', 'geforce_backend_bind',
                   'geforce_backend_wc_bind', 'geforce_backend_stop_bind', 'geforce_heat_stop_request']
        subprocess.run([*flags, '-DOS32_GEFORCE_MODULE',
                        *['-D'+name+'=c3_real_'+name for name in aliases],
                        '-c', str(tree/'drivers/video/geforce/backend_geforce.c'),
                        '-o', str(obj)], check=True)
        objects.append(str(obj))
    subprocess.run([*flags, str(tree/f'tools/tests/gf4_{case}_host.c'),
                    *[str(tree/rel) for rel in sources], *objects, '-o', str(exe)], check=True)
    kwargs = {}
    if case == 'c3':
        from test_module_runtime import image
        kwargs['input'] = struct.pack('<II', 0, 0)+image()
    return host32.run([str(exe)], timeout=180, capture_output=True, **kwargs)


def gf4_main(mutate=False, selected=None):
    cases = list(GF4_COMPONENTS)+list(GF4_LIFECYCLE)
    if selected:
        cases = selected
    failures = 0
    with tempfile.TemporaryDirectory(prefix='gf4-display-') as td:
        directory = Path(td)
        tree = directory/'tree'
        gf4_tree(tree)
        for case in cases:
            try:
                result = gf4_case(tree, case, directory)
            except subprocess.CalledProcessError:
                print(f'FAIL GF4 {case}: compile/link', flush=True)
                failures += 1
                continue
            if result.returncode:
                print(f'FAIL GF4 {case}: runtime rc={result.returncode}\n{(result.stdout+result.stderr).decode(errors="replace")}', flush=True)
                failures += 1
                continue
            print(f'PASS GF4 {case}: runtime GREEN', flush=True)
            if mutate:
                for owner, name, rel, old, new, observation in GF4_MUTATIONS:
                    if owner != case:
                        continue
                    path = tree/rel
                    original = path.read_text()
                    assert original.count(old) == 1, (case, name)
                    try:
                        path.write_text(original.replace(old, new, 1))
                        try:
                            red = gf4_case(tree, case, directory)
                        except subprocess.CalledProcessError:
                            print(f'FAIL MUTATE {case}/{name}: compile/link (not runtime RED)', flush=True)
                            failures += 1
                            continue
                        if not red.returncode:
                            print(f'FAIL MUTATE {case}/{name}: survived ({observation})', flush=True)
                            failures += 1
                        else:
                            print(f'PASS MUTATE {case}/{name}: runtime RED rc={red.returncode}', flush=True)
                    finally:
                        path.write_text(original)
                        restored = gf4_case(tree, case, directory)
                        if restored.returncode:
                            failures += 1
                            print(f'FAIL GF4 {case}/{name}: restored runtime', flush=True)
                        else:
                            print(f'PASS GF4 {case}/{name}: restored runtime GREEN', flush=True)
    return int(bool(failures))


if __name__ == '__main__':
    selection = [arg.split('=', 1)[1] for arg in sys.argv if arg.startswith('--case=')]
    rc = gf4_main('--mutate' in sys.argv, selection or None)
    if not selection:
        legacy_rc = main()
        rc = rc or legacy_rc
        if not legacy_rc and '--mutate' in sys.argv:
            mutations()
    raise SystemExit(rc)
